 results['annexation']=p.evaluate('''()=>{__townTest.reset('settlement',42);const g=__urban.town(),total=__urban.money();g.treasury+=2000000;g.region-=2000000;const ps=__urban.parcels();if(ps.length!==21)throw Error('Atlas parcel count');if(__urban.annex(ps[0].id,__urban.survey(ps[0].id).price+1))throw Error('Wrong quote accepted');const funds=g.treasury;g.region+=funds;g.treasury=0;if(__urban.annex(ps[0].id,__urban.survey(ps[0].id).price))throw Error('Unfunded purchase');g.region-=funds;g.treasury=funds;if(__urban.annex('belt-102-102',__urban.survey('belt-102-102').price))throw Error('Detached purchase');let acquired=0;for(const q of ps){if(!__urban.annex(q.id,__urban.survey(q.id).price))throw Error('Purchase failed '+q.id);acquired++;if(__urban.annex(q.id,__urban.survey(q.id).price))throw Error('Duplicate purchase');}const archive=__townTest.save();if(!__townTest.load(archive))throw Error('Full atlas restore failed');if(Math.abs(__urban.money()-total)>.01)throw Error('Annexation cash drift');return {parcels:acquired,grid:JSON.parse(archive).gridSize,totalArea:ps.reduce((n,q)=>n+q.w*q.h,56*56),conserved:true,valid:__townTest.validate()};}''')
