 results['migration']=p.evaluate('''text=>{const before=JSON.parse(text);for(const o of before.regionalTrade.shipments){o.activePath=o.path.slice(0,2);o.depotIndex=1;}const normalized=__urban.normalize(before);for(let i=0;i<before.regionalTrade.shipments.length;i++){const a=before.regionalTrade.shipments[i],b=normalized.regionalTrade.shipments[i];if(b.depotIndex!==1||b.activePath.some((id,n)=>id!==Math.floor(a.activePath[n]/80)*128+a.activePath[n]%80))throw Error('Active path/index migration');}if(!__townTest.load(before))throw Error('80-grid import rejected');const after=JSON.parse(__townTest.save());if(after.people.length!==before.people.length||after.buildings.some((b,i)=>b.id!==before.buildings[i].id||b.x!==before.buildings[i].x||b.y!==before.buildings[i].y))throw Error('Lost property identity');for(const [id,owner] of Object.entries(before.fieldOwner))if(after.fieldOwner[Math.floor(+id/80)*128+(+id%80)]!==owner)throw Error('Lost crop title');__townTest.step(40);return {from:80,to:after.gridSize,buildings:after.buildings.length,cargo:before.regionalTrade.shipments.length,activePathRemapped:true,identityPreserved:true,valid:__townTest.validate()};}''',legacy)
 results['clearance']=p.evaluate('''()=>{__townTest.reset('settlement',42);const g=__urban.town();const home=g.buildings.find(b=>b.kind==='home'&&g.households[b.hh]?.people.length);const blocked=__urban.quote(home.x,home.y);if(blocked.ok)throw Error('Displacement without real housing allowed');let x,y;outer:for(y=8;y<48;y++)for(x=8;x<48;x++)if(__urban.site(x,y,'home'))break outer;const vacant={id:g.nextId++,kind:'home',x,y,value:48000,condition:100,owner:-2,firm:-1,hh:-1,title:{kind:'investor',id:0}};g.buildings.push(vacant);g.homes.push(vacant.id);__urban.refresh();const q=__urban.quote(home.x,home.y);if(!q.ok||!q.compensation)throw Error('Missing quote/title compensation');const before=__urban.money(),personIds=g.households[home.hh].people.slice(),owner=g.households[home.owner],cash=owner?.cash;const r=__urban.clear(home.x,home.y,q.total);if(!r.ok)throw Error(r.reason);if(g.households[home.hh].home!==vacant.id||JSON.stringify(g.households[home.hh].people)!==JSON.stringify(personIds))throw Error('Lost tenant identity');if(Math.abs(before-__urban.money())>.01)throw Error('Clearance cash drift');if(g.buildings.some(b=>b.id===home.id))throw Error('Home not cleared');if(!__urban.site(home.x,home.y,'park'))throw Error('Cleared land unavailable');return {blockedWithoutVacancy:true,ownerCompensation:q.compensation,relocatedHouseholds:q.households.length,totalCost:q.total,conserved:true,valid:__townTest.validate(),vacant:vacant.id};}''')
 results['farmClearance']=p.evaluate('''()=>{__townTest.reset('settlement',42);const g=__urban.town(),farm=g.firms.find(f=>f.kind==='farm'),site=g.buildings.find(b=>b.id===farm.building),before=__urban.money(),qty=JSON.stringify(farm.stock),q=__urban.quote(site.x,site.y);if(!q.ok)throw Error(q.reason);const workers=farm.workers.slice(),fields=q.fields.length;if(!__urban.clear(site.x,site.y,q.total).ok)throw Error('Farm clearance');if(!farm.closed||workers.some(id=>g.people[id].job>=0)||Object.values(g.fieldOwner).includes(farm.id))throw Error('Farm not closed/released');if(Math.abs(__urban.money()-before)>.01)throw Error('Liquidation drift');return {fieldsReleased:fields,workersCompensated:workers.length,conserved:true,goods:__townTest.goods(),valid:__townTest.validate()};}''')
 results['planning']=p.evaluate('''()=>{__townTest.reset('settlement',42);const g=__urban.town(),b=g.buildings.find(b=>b.kind==='home'),before=__urban.money();const a=__urban.plan(b.x,b.y,'residential');if(!a.ok)throw Error(a.reason);if(__urban.site(b.x+1,b.y,'farm'))throw Error('Farm in residential plan');if(__urban.plan(b.x,b.y,'agriculture').ok)throw Error('Plan oscillation');__urban.review();const initial=JSON.parse(JSON.stringify(g.urban.districts));g.day+=30;__urban.review();if(Object.keys(initial).length!==Object.keys(g.urban.districts).length)throw Error('District instability');if(Math.abs(before-__urban.money())>.01)throw Error('Planning cash drift');return {districts:Object.keys(initial).length,revisionCooldown:true,conserved:true};}''')
 results['mall']=p.evaluate('''()=>{__townTest.reset('settlement',42);const g=__urban.town();for(const h of g.households){for(let j=0;j<18;j++){const a={id:g.people.length,name:'Controlled catchment worker',age:29,skill:.7,health:90,hh:h.id,job:-1,life:70,last:[]};g.people.push(a);h.people.push(a.id);}}__urban.refresh();g.stats.marketConfidence=75;const total=__urban.money(),r=__urban.retail(true);if(!r.ok)throw Error(r.reason);const project=g.projects.find(p=>p.retailCentre),site=g.buildings.find(b=>b.id===project.id);if(project.urbanEscrow!==28000||site.footprint.length!==6)throw Error('Missing mall escrow/footprint');if(Math.abs(total-__urban.money())>.01)throw Error('Mall funding drift');if(!__townTest.load(__townTest.save()))throw Error('Mall escrow restore');const after=__urban.town(),pending=after.projects.find(p=>p.retailCentre);pending.remaining=1;__urban.complete();const firm=after.firms.find(f=>f.retailCentre);if(!firm||firm.cash!==28000||firm.jobs!==8)throw Error('Mall commissioning');if(Math.abs(total-__urban.money())>.01)throw Error('Mall completion drift');return {catchment:firm.retailCatchment,capital:firm.cash,jobs:firm.jobs,footprint:6,conserved:true,valid:__townTest.validate()};}''')
 results['farmRenewal']=p.evaluate('''()=>{__townTest.reset('settlement',42);const g=__urban.town();g.treasury+=600000;g.region-=600000;const farms=g.firms.filter(f=>f.kind==='farm').map(f=>({f,b:g.buildings.find(b=>b.id===f.building)})).sort((a,b)=>__urban.descriptor(b.b.x,b.b.y).density-__urban.descriptor(a.b.x,a.b.y).density),{f,b}=farms[0];for(let r=1;r<=6&&__urban.descriptor(b.x,b.y).density<6;r++)for(let dy=-r;dy<=r;dy++)for(let dx=-r;dx<=r;dx++){if(Math.abs(dx)+Math.abs(dy)!==r||__urban.descriptor(b.x,b.y).density>=6)continue;const x=b.x+dx,y=b.y+dy;if(__urban.site(x,y,'home'))__urban.build('home',x,y);}const before=__urban.money(),stock=JSON.stringify(f.stock),origin={x:b.x,y:b.y},id=b.id,workers=f.workers.slice();if(!__urban.renew({homeDemand:80,housingPressure:90,confidence:80}))throw Error('Farm renewal unavailable density '+__urban.descriptor(b.x,b.y).density);if(b.id!==id||b.x===origin.x&&b.y===origin.y||JSON.stringify(f.stock)!==stock||JSON.stringify(f.workers)!==JSON.stringify(workers))throw Error('Farm enterprise identity lost');if(Math.abs(before-__urban.money())>.01)throw Error('Farm renewal cash drift');const p=g.projects.find(p=>p.urbanRenewal),site=g.buildings.find(b=>b.id===p.id);if(site.footprint.length!==4||p.target!=='apartment')throw Error('Missing replacement housing');if(__urban.renew({homeDemand:80,housingPressure:90,confidence:80}))throw Error('Parallel renewal allowed');return {farmId:f.id,buildingId:id,relocated:true,stocksPreserved:true,workersPreserved:true,replacementUnits:p.units,conserved:true,valid:__townTest.validate()};}''')
 results['districtLifecycle']=p.evaluate('''()=>{__townTest.reset('settlement',42);const g=__urban.town();g.day=30;__urban.review();const [key,d]=Object.entries(g.urban.districts).find(([k,d])=>d.character!=='Mixed quarter'),old=d.character,ids=new Set(__urban.spatial().blocks[key].buildings);for(const b of g.buildings)if(ids.has(b.id)){b.kind='park';b.firm=-1;b.hh=-1;}g.households=g.households.map(h=>ids.has(h.home)?{...h,people:[]}:h);__urban.refresh();g.day=60;__urban.review();g.day=120;__urban.review();if(d.character!==old)throw Error('Character changed before persistence');g.day=150;__urban.review();if(d.character===old)throw Error('Persistent district evolution missing');g.buildings=g.buildings.filter(b=>!ids.has(b.id));__urban.refresh();g.day=180;__urban.review();g.day=330;__urban.review();if(!g.urban.districts[key])throw Error('District dissolved too early');g.day=360;__urban.review();if(g.urban.districts[key])throw Error('Empty district never dissolved');return {controlledLifecycleFixture:true,characterHoldDays:90,dissolutionHoldDays:180};}''')
