 results['endurance']=p.evaluate('''()=>{const runs=[];for(const seed of [42,101]){__townTest.reset('settlement',seed);const total=__urban.money(),start=performance.now();__townTest.step(1080);const saved=__townTest.save(),v=__townTest.validate();if(!v.ok||Math.abs(total-v.total)>.05)throw Error(v.issues.join(';')+' cash '+(v.total-total));if(!__townTest.load(saved))throw Error('Long save rejected');runs.push({seed,day:__townTest.get().day,population:__townTest.get().population,ms:performance.now()-start,moneyError:v.total-total,districts:Object.keys(__urban.town().urban.districts).length});}return runs;}''')
